// The Turkish grammar cheat sheet for dailyturkish.app (grammar-cheat-sheet.html), written by scripts/turkish/static.mjs
// (mirror only). Every Turkish example is built by the morphology engine, assets/js/turkish-morph.js, so the tables
// can't drift from what the course teaches; each section links to the guide section that explains it.
import { TENSES, verbSlug } from "./static-verbs.mjs";

export const CHEAT_CSS = `
      /* Grammar cheat sheet, generated by scripts/turkish/static-cheatsheet.mjs */
      .cs-toc { columns: 2 240px; column-gap: 32px; margin: 0 0 8px; padding-left: 20px; font-size: 14.5px; }
      .cs-toc li { break-inside: avoid; margin-bottom: 4px; }
      .cs { margin-top: 34px; scroll-margin-top: 80px; }
      .cs > h2 { font-size: 21px; font-weight: 650; letter-spacing: -0.01em; }
      .cs-lede { max-width: 46em; margin: 6px 0 12px; font-size: 15px; }
      .cs-learn { font-size: 13.5px; color: var(--muted); margin: 8px 0 0; }
      .cs-wrap { overflow-x: auto; }
      table.cs-t { border-collapse: collapse; font-size: 14.5px; min-width: 100%; }
      table.cs-t th, table.cs-t td { text-align: left; padding: 7px 10px; border-bottom: 1px solid var(--line); vertical-align: top; }
      table.cs-t th { font-size: 11.5px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--muted); white-space: nowrap; }
      table.cs-t td { color: var(--body); }
      table.cs-t td [lang="tr"] { color: var(--ink); }
      table.cs-t td.k { color: var(--ink); font-weight: 600; white-space: nowrap; }
      table.cs-t code { font-size: 13px; white-space: nowrap; }
      .cs-pair { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px 32px; }
      @media (max-width: 899px) { .cs-pair { grid-template-columns: minmax(0, 1fr); } }
      .cs-rules { max-width: 46em; padding-left: 20px; margin: 6px 0 0; font-size: 14.5px; }
      .cs-rules li + li { margin-top: 6px; }
      @media (max-width: 599px) { table.cs-t th, table.cs-t td { padding: 6px 6px; } table.cs-t { font-size: 13.5px; } }
    `;

// ctx: { M, text, guideLink, verbLinks }
export function cheatSheetBody(ctx) {
  const { M, text, guideLink, verbLinks } = ctx;
  const t = (w) => M.text(w);
  const tr = (s) => `<span lang="tr">${text(s)}</span>`;
  const code = (s) => `<code>${text(s)}</code>`;
  const P = M.PERSONS;
  const learn = (...gps) => {
    const ls = gps.map(guideLink).filter(Boolean);
    return ls.length ? `<p class="cs-learn">Learn more: ${ls.map((g) => `<a href="${g.href}">${text(g.label)}</a>`).join(" · ")}</p>` : "";
  };
  const tbl = (head, rows) => `<div class="cs-wrap"><table class="cs-t"><thead><tr>${head.map((h) => `<th>${h}</th>`).join("")}</tr></thead><tbody>` +
    rows.map((r) => `<tr>${r.map((c, i) => `<td${i === 0 ? ' class="k"' : ""}>${c}</td>`).join("")}</tr>`).join("") + "</tbody></table></div>";
  const sec = (id, title, html) => ({ id, title, html: `      <section class="cs" id="${id}" aria-labelledby="h-${id}">
        <h2 id="h-${id}">${text(title)}</h2>
${html}
      </section>` });
  const verb = (v) => (verbLinks.has(v) ? `<a href="${verbLinks.get(v)}" lang="tr">${text(v)}</a>` : tr(v));
  const form = (slug, v, p) => { const r = M.form(slug, v, p); if (!r) throw new Error(`cheat sheet: no ${slug} of ${v} for ${p}`); return r.text; };
  const n = M.noun, V = M.verb;
  const NOUNS = ["ev", "araba", "kitap", "okul"];
  const CASES = [["Nominative", null, "—", "the subject; an indefinite object", "gp-sentence-basics"], ["Accusative", "acc", "-(y)I", "the (definite object)", "gp-accusative"],
    ["Dative", "dat", "-(y)A", "to, toward", "gp-dative"], ["Locative", "loc", "-DA", "in, at, on", "gp-locative"], ["Ablative", "abl", "-DAn", "from, out of", "gp-ablative"],
    ["Genitive", "gen", "-(n)In", "of, …'s", "gp-genitive"], ["With", "ins", "-(y)lA", "with, by", "gp-ile"]];
  const S = [];

  S.push(sec("harmony", "Vowel harmony", `        <p class="cs-lede">Suffixes change their vowel to match the last vowel of the word. In the course, ${code("A")} is a two-way vowel (a or e) and ${code("I")} a four-way vowel (ı, i, u or ü).</p>
        ${tbl(["Last vowel of the word", "A becomes", "I becomes", "Examples"], [
          ["a, ı", tr("a"), tr("ı"), `${tr(t(M.plural(n("kız"))))}, ${tr(t(M.addCase(n("kız"), "acc")))}`],
          ["o, u", tr("a"), tr("u"), `${tr(t(M.plural(n("okul"))))}, ${tr(t(M.addCase(n("okul"), "acc")))}`],
          ["e, i", tr("e"), tr("i"), `${tr(t(M.plural(n("ev"))))}, ${tr(t(M.addCase(n("ev"), "acc")))}`],
          ["ö, ü", tr("e"), tr("ü"), `${tr(t(M.plural(n("göz"))))}, ${tr(t(M.addCase(n("göz"), "acc")))}`]])}
        ${learn("gp-harmony-2way", "gp-harmony-4way", "gp-harmony-exceptions")}`));

  S.push(sec("consonants", "Consonant changes and buffer letters", `        <ul class="cs-rules">
          <li><b>d or t:</b> ${code("D")} is t after f, s, t, k, ç, ş, h, p (“fıstıkçı şahap”), d elsewhere: ${tr(t(M.addCase(n("kitap"), "loc")))}, ${tr(t(M.addCase(n("sokak"), "abl")))}, but ${tr(t(M.addCase(n("ev"), "loc")))}.</li>
          <li><b>Softening:</b> a final p, ç, t, k usually becomes b, c, d, ğ before a vowel: ${tr("kitap")} → ${tr(t(M.addCase(n("kitap"), "acc")))}, ${tr("ağaç")} → ${tr(t(M.addCase(n("ağaç"), "acc")))}, ${tr("çocuk")} → ${tr(t(M.addCase(n("çocuk"), "dat")))}. Most one-syllable words keep theirs: ${tr(t(M.addCase(n("top"), "acc")))}.</li>
          <li><b>Buffer y:</b> after a vowel, suffixes that start with a vowel take a y: ${tr(t(M.addCase(n("araba"), "dat")))}, ${tr(t(M.addCase(n("araba"), "acc")))}, ${tr(form("copula-present", "öğrenci", "ben"))}.</li>
          <li><b>Buffer s and n:</b> the possessive of “his, her, its” is -sI after a vowel (${tr(t(M.possessive(n("araba"), "o")))}), and a case ending after it takes an n: ${tr(t(M.addCase(M.possessive(n("araba"), "o"), "loc")))}.</li>
          <li><b>Names</b> keep an apostrophe before the suffix: ${tr(t(M.addCase(n("İstanbul"), "loc")))}, ${tr(t(M.addCase(n("Türkiye"), "dat")))}.</li>
        </ul>
        ${learn("gp-consonant-assimilation", "gp-consonant-softening", "gp-buffer-letters", "gp-pronominal-n", "gp-apostrophe")}`));

  S.push(sec("cases", "The six cases, and -(y)lA", `        <p class="cs-lede">Turkish has no prepositions for in, to or from: a case ending on the noun does the job. The plural ${code("-lAr")} comes first, then the possessive, then the case: ${tr(t(M.addCase(M.possessive(M.plural(n("ev")), "ben"), "loc")))} (in my houses).</p>
        ${tbl(["Case", "Suffix", "Meaning"].concat(NOUNS), CASES.map(([name, c, suf, mean]) => [name, code(suf), text(mean)].concat(NOUNS.map((w) => tr(c ? t(M.addCase(n(w), c)) : w)))))}
        ${learn(...CASES.map((c) => c[4]).slice(1))}`));

  S.push(sec("possessive", "Possessive endings: my, your, his", `        ${tbl(["Owner", "Suffix", "ev", "araba", "kitap", "okul"], P.map((p, i) => [p,
          code(["-(I)m", "-(I)n", "-(s)I", "-(I)mIz", "-(I)nIz", "-lArI"][i]), tr(t(M.possessive(n("ev"), p))), tr(t(M.possessive(n("araba"), p))), tr(t(M.possessive(n("kitap"), p))), tr(t(M.possessive(n("okul"), p)))]))}
        <p class="cs-learn">To say “I have”: possessive + ${tr("var")}: ${tr(form("possessive-var", "araba", "ben"))} (I have a car); “of”: genitive + possessive: ${tr(t(M.addCase(n("Ayşe"), "gen")))} ${tr(t(M.possessive(n("ev"), "o")))} (Ayşe's house).</p>
        ${learn("gp-possessive-suffixes", "gp-possessive-have", "gp-genitive-possessive")}`));

  S.push(sec("pronouns", "Personal pronouns", `        ${tbl(["", "Accusative", "Dative", "Locative", "Ablative", "Genitive"], P.map((p) => [p].concat(
          ["accusative", "dative", "locative", "ablative", "genitive"].map((c) => tr(form("pronoun-" + c, "", p))))))}
        ${learn("gp-personal-pronouns", "gp-pronoun-accusative", "gp-pronoun-cases-dat-abl", "gp-genitive")}`));

  S.push(sec("to-be", "“To be”: the personal endings", `        <p class="cs-lede">There is no verb “to be” in the present: an ending goes on the noun or adjective. ${tr("değil")} makes it negative and carries the ending; the question particle ${tr("mi")} is written apart.</p>
        ${tbl(["Person", "Suffix", "I am a student", "I'm not tired", "Am I ready?", "I was at home"], P.map((p, i) => [p,
          code(["-(y)Im", "-sIn", "—", "-(y)Iz", "-sInIz", "-lAr"][i]), tr(form("copula-present", "öğrenci", p)), tr(form("copula-present-negative", "yorgun", p)),
          tr(form("copula-present-question", "hazır", p)), tr(form("past-copula", "evde", p))]))}
        ${learn("gp-copula-present", "gp-degil", "gp-question-mi", "gp-past-copula")}`));

  S.push(sec("personal-endings", "The two sets of personal endings on verbs", `        <p class="cs-lede">Most tenses take the same endings as “to be” (set 1). The past ${code("-DI")} and the conditional ${code("-sA")} take short endings (set 2).</p>
        ${tbl(["Person", "Set 1", "Example", "Set 2", "Example"], P.map((p, i) => [p, code(["-(y)Im", "-sIn", "—", "-(y)Iz", "-sInIz", "-lAr"][i]), tr(form("present-continuous", "gelmek", p)),
          code(["-m", "-n", "—", "-k", "-nIz", "-lAr"][i]), tr(form("past", "gelmek", p))]))}
        ${learn("gp-person-endings-types")}`));

  S.push(sec("tenses", "Tenses and moods at a glance", `        <p class="cs-lede">The forms for ben (I). The negative ${code("-mA")} goes right after the stem (${tr(form("present-continuous-negative", "gelmek", "ben"))}); the aorist has its own negative ${code("-mAz")} (${tr(form("aorist-negative", "gelmek", "o"))}). Full tables for 100 verbs: <a href="/verbs/">Turkish verbs</a>.</p>
        ${tbl(["Tense", "Suffix", "gelmek", "yapmak", "okumak", "Used for"], TENSES.map(([s, name, suf, what, gp]) => {
          const g = guideLink(gp), p = s === "imperative" ? "sen" : "ben";
          return [g ? `<a href="${g.href}">${text(name)}</a>` : text(name), code(suf), tr(form(s, "gelmek", p)), tr(form(s, "yapmak", p)), tr(form(s, "okumak", p)), text(what)];
        }))}
        <p class="cs-learn">Questions: ${tr(form("present-continuous-question", "gelmek", "sen"))}, ${tr(form("past-question", "gelmek", "sen"))}, ${tr(form("future-question", "gelmek", "sen"))}. Conjugated in full: ${["gelmek", "yapmak", "okumak", "gitmek", "etmek", "demek"].map(verb).join(", ")}.</p>`));

  const conv = [["-(y)Ip", "and (then)", "(y)Ip", "gp-ip"], ["-(y)IncA", "when, once", "(y)IncA", "gp-ince"], ["-(y)ArAk", "by …ing, while", "(y)ArAk", "gp-arak"],
    ["-mAdAn", "without; (önce) before", "mAdAn", "gp-madan"], ["-DIktAn sonra", "after", "DIktAn", "gp-dikten-sonra"], ["-DIkçA", "the more, whenever", "DIkçA", "gp-dikca"],
    ["-(y)AlI", "since", "(y)AlI", "gp-ali"]];
  S.push(sec("converbs", "Linking clauses: -ip, -ince, -erek…", `        ${tbl(["Suffix", "Meaning", "gelmek", "yapmak", "okumak"], [[code("-(y)ken"), "while", tr(form("aorist", "gelmek", "o") + "ken"), tr(form("aorist", "yapmak", "o") + "ken"), tr(form("aorist", "okumak", "o") + "ken")]]
          .concat(conv.map(([suf, mean, tpl]) => [code(suf), text(mean)].concat(["gelmek", "yapmak", "okumak"].map((v) => tr(t(M.attach(V(v), tpl)) + (tpl === "DIktAn" ? " sonra" : "")))))))}
        ${learn("gp-ken", ...conv.map((c) => c[3]))}`));

  S.push(sec("participles", "Participles: the …ing man, the book I read", `        <p class="cs-lede">Relative clauses come before the noun, built on a participle.</p>
        ${tbl(["Suffix", "Use", "Example", "Meaning"], [
          [code("-(y)An"), "the doer does it", `${tr("kitap " + t(M.attach(V("okumak"), "(y)An")) + " kız")}`, "the girl who is reading a book"],
          [code("-DIK") + " + possessive", "someone else does it (past, present)", `${tr(t(M.possessive(M.attach(V("okumak"), "DIK"), "ben")) + " kitap")}`, "the book I read"],
          [code("-(y)AcAK") + " + possessive", "someone else will do it", `${tr(t(M.possessive(M.attach(V("okumak"), "(y)AcAK"), "ben")) + " kitap")}`, "the book I will read"],
          [code("-(y)AcAK"), "something to be done", `${tr(t(M.attach(V("kalmak"), "(y)AcAK")) + " yer")}`, "a place to stay"],
          [code("-mIş"), "a finished state", `${tr(t(M.attach(V("pişmek"), "mIş")) + " tavuk")}`, "cooked chicken"]])}
        ${learn("gp-participle-an", "gp-participle-dik", "gp-participle-acak", "gp-mis-adjective")}`));

  S.push(sec("voices", "Voices: passive, causative, reflexive, reciprocal", `        ${tbl(["Voice", "Suffix", "Examples"], [
          ["Passive", code("-Il, -In, -n"), ["yapmak", "görmek", "okumak", "bulmak"].map((v) => tr(t(M.attach(M.passive(V(v)), "mAk")))).join(", ")],
          ["Causative", code("-DIr, -t, -Ir, -Ar"), ["yapmak", "okumak", "ölmek", "gelmek", "görmek"].map((v) => tr(t(M.attach(M.causative(V(v)), "mAk")))).join(", ")],
          ["Reflexive", code("-In, -n"), ["yıkamak", "giymek", "taramak"].map((v) => tr(t(M.attach(M.reflexive(V(v)), "mAk")))).join(", ")],
          ["Reciprocal", code("-Iş, -ş"), ["görmek", "bulmak", "tanımak"].map((v) => tr(t(M.attach(M.reciprocal(V(v)), "mAk")))).join(", ")]])}
        <p class="cs-learn">They stack in a fixed order: stem, reflexive or reciprocal, causative, passive, then negative, tense and person: ${tr(form("past", t(M.attach(M.passive(M.causative(V("yapmak"))), "mAk")), "o"))} (someone had it done).</p>
        ${learn("gp-passive", "gp-causative", "gp-reflexive", "gp-reciprocal", "gp-voice-order")}`));

  S.push(sec("word-order", "Word order", `        <ul class="cs-rules">
          <li>The verb comes last: subject, object, verb. ${tr("Ali kitabı okudu.")} (Ali read the book.)</li>
          <li>Whatever stands right before the verb is in focus: ${tr("Kitabı Ali okudu.")} (It was Ali who read the book.)</li>
          <li>Adjectives, possessors and relative clauses come before the noun; ${tr("bir")} (a, an) comes after the adjective: ${tr("güzel bir ev")}.</li>
          <li>Postpositions come after their noun: ${tr("senin için")} (for you), ${tr(t(M.addCase(n("ders"), "abl")) + " sonra")} (after the lesson).</li>
          <li>The subject pronoun is usually left out, since the ending already says who: ${tr(form("present-continuous", "gelmek", "ben"))}.</li>
        </ul>
        ${learn("gp-sentence-basics", "gp-object-word-order", "gp-relative-order", "gp-postp-nominative")}`));

  return { toc: S.map((s) => [s.id, s.title]), html: S.map((s) => s.html).join("\n") };
}
